MODULE_SOURCE='from __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom types import MappingProxyType\nfrom typing import Any, Mapping, Tuple\n\nfrom .universal_market_discovery_foundation import (\n    UMD_SUBSYSTEM_ID,\n    ImmutableLineage,\n    deterministic_sha256,\n)\nfrom .certified_active_canonical_market_registry_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model import (\n    CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModel,\n)\n\nUMD_041_BUILD_ID = "UMD-041"\nUMD_041_BUILD_NAME = (\n    "Certified Active Canonical Market Registry Query Session "\n    "Read Model Admission Ledger Read Model Admission Ledger Read Model Admission Gate"\n)\nUMD_041_REVISION = (\n    "UMD_041_CERTIFIED_ACTIVE_CANONICAL_MARKET_REGISTRY_QUERY_SESSION_"\n    "READ_MODEL_ADMISSION_LEDGER_READ_MODEL_ADMISSION_LEDGER_READ_MODEL_"\n    "ADMISSION_LEDGER_READ_MODEL_ADMISSION_GATE_V1"\n)\nUMD_041_SCHEMA_VERSION = "1.0.0"\n\nPROHIBITED_CAPABILITIES = (\n    "network_discovery",\n    "market_scanning",\n    "automatic_admission_commit",\n    "ledger_append",\n    "ledger_mutation",\n    "read_model_mutation",\n    "read_model_persistence",\n    "active_registry_mutation",\n    "oracle_memory_mutation",\n    "publication",\n    "order_submission",\n    "trade_execution",\n)\n\n\ndef _text(value: str, field_name: str) -> str:\n    if not isinstance(value, str):\n        raise TypeError(f"{field_name} must be a string")\n    normalized = " ".join(value.strip().split())\n    if not normalized:\n        raise ValueError(f"{field_name} must not be empty")\n    return normalized\n\n\ndef _sha256(value: str, field_name: str) -> str:\n    normalized = _text(value, field_name).lower()\n    if len(normalized) != 64:\n        raise ValueError(f"{field_name} must contain 64 hexadecimal characters")\n    if any(character not in "0123456789abcdef" for character in normalized):\n        raise ValueError(f"{field_name} must be lowercase SHA-256 hexadecimal")\n    return normalized\n\n\n@dataclass(frozen=True, slots=True)\nclass CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionDecision:\n    read_model_hash: str\n    source_ledger_hash: str\n    admitted: bool\n    checks: Mapping[str, bool]\n    rejection_reasons: Tuple[str, ...]\n    lineage: ImmutableLineage\n\n    def __post_init__(self) -> None:\n        object.__setattr__(self, "read_model_hash", _sha256(self.read_model_hash, "read_model_hash"))\n        object.__setattr__(self, "source_ledger_hash", _sha256(self.source_ledger_hash, "source_ledger_hash"))\n\n        normalized_checks = {\n            _text(str(name), "check name"): bool(passed)\n            for name, passed in self.checks.items()\n        }\n        object.__setattr__(\n            self,\n            "checks",\n            MappingProxyType(dict(sorted(normalized_checks.items()))),\n        )\n\n        failed = tuple(name for name, passed in self.checks.items() if not passed)\n        reasons = tuple(sorted({_text(reason, "rejection reason") for reason in self.rejection_reasons}))\n        object.__setattr__(self, "rejection_reasons", reasons)\n\n        if self.admitted:\n            if failed or reasons:\n                raise ValueError("admitted decision cannot contain failures")\n        else:\n            if not failed:\n                raise ValueError("rejected decision requires failed checks")\n            if reasons != tuple(sorted(failed)):\n                raise ValueError("rejection reasons must match failed checks")\n\n        if self.lineage.subsystem_id != UMD_SUBSYSTEM_ID:\n            raise ValueError("admission lineage must belong to UMD")\n        if self.lineage.build_id != UMD_041_BUILD_ID:\n            raise ValueError("admission lineage must use build_id UMD-041")\n        required = {self.read_model_hash, self.source_ledger_hash}\n        if not required.issubset(set(self.lineage.parent_hashes)):\n            raise ValueError("admission lineage is missing required parent hashes")\n\n    @property\n    def decision_id(self) -> str:\n        return (\n            "umd:query-session-read-model-admission-ledger-read-model-admission:"\n            + deterministic_sha256(\n                {\n                    "read_model_hash": self.read_model_hash,\n                    "source_ledger_hash": self.source_ledger_hash,\n                    "admitted": self.admitted,\n                    "checks": self.checks,\n                }\n            )\n        )\n\n    def to_canonical_dict(self) -> Mapping[str, Any]:\n        return {\n            "decision_id": self.decision_id,\n            "read_model_hash": self.read_model_hash,\n            "source_ledger_hash": self.source_ledger_hash,\n            "admitted": self.admitted,\n            "checks": self.checks,\n            "rejection_reasons": self.rejection_reasons,\n            "lineage": self.lineage,\n        }\n\n    @property\n    def record_hash(self) -> str:\n        return deterministic_sha256(self.to_canonical_dict())\n\n\ndef evaluate_active_market_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model(\n    read_model: CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModel,\n    *,\n    lineage: ImmutableLineage,\n) -> CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionDecision:\n    if not isinstance(\n        read_model,\n        CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModel,\n    ):\n        raise TypeError("read_model must be a certified UMD-037 read model")\n\n    checks = {\n        "read_model_hash_deterministic": (\n            read_model.read_model_hash\n            == deterministic_sha256(read_model.to_canonical_dict())\n        ),\n        "count_partition_valid": (\n            read_model.admitted_entry_count\n            + read_model.rejected_entry_count\n            == read_model.total_entry_count\n        ),\n        "ordered_entry_count_valid": (\n            len(read_model.ordered_entry_ids) == read_model.total_entry_count\n        ),\n        "ordered_read_model_count_valid": (\n            len(read_model.ordered_read_model_hashes) == read_model.total_entry_count\n        ),\n        "ordered_decision_count_valid": (\n            len(read_model.ordered_decision_ids) == read_model.total_entry_count\n        ),\n        "entry_ids_unique": (\n            len(set(read_model.ordered_entry_ids))\n            == len(read_model.ordered_entry_ids)\n        ),\n        "read_model_hashes_unique": (\n            len(set(read_model.ordered_read_model_hashes))\n            == len(read_model.ordered_read_model_hashes)\n        ),\n        "decision_ids_unique": (\n            len(set(read_model.ordered_decision_ids))\n            == len(read_model.ordered_decision_ids)\n        ),\n        "admission_partition_disjoint": (\n            not set(read_model.admitted_entry_ids).intersection(\n                read_model.rejected_entry_ids\n            )\n        ),\n        "admission_partition_complete": (\n            set(read_model.admitted_entry_ids).union(\n                read_model.rejected_entry_ids\n            )\n            == set(read_model.ordered_entry_ids)\n        ),\n        "latest_entry_consistent": (\n            (\n                read_model.latest_entry_id is None\n                and not read_model.ordered_entry_ids\n            )\n            or (\n                bool(read_model.ordered_entry_ids)\n                and read_model.latest_entry_id\n                == read_model.ordered_entry_ids[-1]\n            )\n        ),\n        "latest_admitted_entry_consistent": (\n            (\n                read_model.latest_admitted_entry_id is None\n                and not read_model.admitted_entry_ids\n            )\n            or (\n                bool(read_model.admitted_entry_ids)\n                and read_model.latest_admitted_entry_id\n                == read_model.admitted_entry_ids[-1]\n            )\n        ),\n        "entry_positions_contiguous": all(\n            read_model.entry_position(entry_id) == index\n            for index, entry_id in enumerate(read_model.ordered_entry_ids, start=1)\n        ),\n        "read_model_positions_contiguous": all(\n            read_model.read_model_position(read_model_hash) == index\n            for index, read_model_hash in enumerate(\n                read_model.ordered_read_model_hashes,\n                start=1,\n            )\n        ),\n        "decision_positions_contiguous": all(\n            read_model.decision_position(decision_id) == index\n            for index, decision_id in enumerate(\n                read_model.ordered_decision_ids,\n                start=1,\n            )\n        ),\n        "lineage_bound_to_source_ledger": (\n            read_model.source_ledger_hash in read_model.lineage.parent_hashes\n        ),\n    }\n\n    failed = tuple(name for name, passed in checks.items() if not passed)\n\n    return CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionDecision(\n        read_model_hash=read_model.read_model_hash,\n        source_ledger_hash=read_model.source_ledger_hash,\n        admitted=not failed,\n        checks=checks,\n        rejection_reasons=failed,\n        lineage=lineage,\n    )\n\n\n@dataclass(frozen=True, slots=True)\nclass UMD041CertificationManifest:\n    subsystem_id: str\n    build_id: str\n    build_name: str\n    revision: str\n    schema_version: str\n    upstream_builds: Tuple[str, ...]\n    gate_mode: str\n    prohibited_capabilities: Tuple[str, ...]\n    network_enabled: bool\n    persistence_enabled: bool\n    mutation_enabled: bool\n    publication_enabled: bool\n    execution_enabled: bool\n\n    def to_canonical_dict(self) -> Mapping[str, Any]:\n        return {\n            "subsystem_id": self.subsystem_id,\n            "build_id": self.build_id,\n            "build_name": self.build_name,\n            "revision": self.revision,\n            "schema_version": self.schema_version,\n            "upstream_builds": self.upstream_builds,\n            "gate_mode": self.gate_mode,\n            "prohibited_capabilities": self.prohibited_capabilities,\n            "network_enabled": self.network_enabled,\n            "persistence_enabled": self.persistence_enabled,\n            "mutation_enabled": self.mutation_enabled,\n            "publication_enabled": self.publication_enabled,\n            "execution_enabled": self.execution_enabled,\n        }\n\n    @property\n    def manifest_hash(self) -> str:\n        return deterministic_sha256(self.to_canonical_dict())\n\n\ndef build_umd_041_certification_manifest() -> UMD041CertificationManifest:\n    return UMD041CertificationManifest(\n        subsystem_id="UMD",\n        build_id=UMD_041_BUILD_ID,\n        build_name=UMD_041_BUILD_NAME,\n        revision=UMD_041_REVISION,\n        schema_version=UMD_041_SCHEMA_VERSION,\n        upstream_builds=tuple(f"UMD-{number:03d}" for number in range(1, 41)),\n        gate_mode="deterministic_read_only_admission",\n        prohibited_capabilities=PROHIBITED_CAPABILITIES,\n        network_enabled=False,\n        persistence_enabled=False,\n        mutation_enabled=False,\n        publication_enabled=False,\n        execution_enabled=False,\n    )\n\n\ndef certify_umd_041_foundation() -> Mapping[str, Any]:\n    manifest = build_umd_041_certification_manifest()\n    checks = {\n        "subsystem_identity": manifest.subsystem_id == "UMD",\n        "build_identity": manifest.build_id == "UMD-041",\n        "upstreams_frozen": (\n            manifest.upstream_builds\n            == tuple(f"UMD-{number:03d}" for number in range(1, 41))\n        ),\n        "deterministic_read_only_admission": (\n            manifest.gate_mode == "deterministic_read_only_admission"\n        ),\n        "network_disabled": manifest.network_enabled is False,\n        "persistence_disabled": manifest.persistence_enabled is False,\n        "mutation_disabled": manifest.mutation_enabled is False,\n        "publication_disabled": manifest.publication_enabled is False,\n        "execution_disabled": manifest.execution_enabled is False,\n        "deterministic_manifest_hash": (\n            manifest.manifest_hash\n            == deterministic_sha256(manifest.to_canonical_dict())\n        ),\n    }\n    failed = tuple(name for name, passed in checks.items() if not passed)\n    return MappingProxyType(\n        {\n            "certified": not failed,\n            "build_id": manifest.build_id,\n            "revision": manifest.revision,\n            "manifest_hash": manifest.manifest_hash,\n            "checks": MappingProxyType(checks),\n            "failed_checks": failed,\n        }\n    )\n\n\ndef verify_umd_041_query_session_read_model_admission_gate() -> bool:\n    certification = certify_umd_041_foundation()\n    if not certification["certified"]:\n        raise RuntimeError(\n            "UMD-041 foundation certification failed: "\n            + ", ".join(certification["failed_checks"])\n        )\n    return True\n'
TEST_SOURCE="from __future__ import annotations\nimport hashlib\nimport unittest\nfrom dataclasses import FrozenInstanceError\nfrom datetime import datetime, timezone\nfrom qseries_v2.universal_market_discovery.universal_market_discovery_foundation import ImmutableLineage\nfrom qseries_v2.universal_market_discovery.certified_active_canonical_market_registry_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model import (\n    UMD_040_REVISION,\n    CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModel,\n)\nfrom qseries_v2.universal_market_discovery.umd_041_query_session_read_model_admission_gate import (\n    UMD_041_REVISION,\n    CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionDecision,\n    build_umd_041_certification_manifest,\n    certify_umd_041_foundation,\n    evaluate_active_market_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model,\n)\nFIXED=datetime(2026,8,6,22,0,0,tzinfo=timezone.utc)\ndef h(s): return hashlib.sha256(s.encode()).hexdigest()\ndef model():\n    ledger=h('umd040-ledger')\n    lin=ImmutableLineage(subsystem_id='UMD',build_id='UMD-040',revision=UMD_040_REVISION,schema_version='1.0.0',parent_hashes=(ledger,),source_refs=('fixture://umd-041/model',),created_at=FIXED)\n    return CertifiedActiveMarketQuerySessionReadModelAdmissionLedgerReadModelAdmissionLedgerReadModelAdmissionLedgerReadModel(\n      source_ledger_hash=ledger,total_entry_count=3,admitted_entry_count=2,rejected_entry_count=1,\n      ordered_entry_ids=('entry-a','entry-b','entry-c'),ordered_read_model_hashes=(h('rm-a'),h('rm-b'),h('rm-c')),\n      ordered_decision_ids=('decision-a','decision-b','decision-c'),admitted_entry_ids=('entry-a','entry-c'),rejected_entry_ids=('entry-b',),\n      latest_entry_id='entry-c',latest_admitted_entry_id='entry-c',metadata={'read_only':True},lineage=lin)\ndef gate_lineage(m):\n    return ImmutableLineage(subsystem_id='UMD',build_id='UMD-041',revision=UMD_041_REVISION,schema_version='1.0.0',parent_hashes=(m.read_model_hash,m.source_ledger_hash),source_refs=('fixture://umd-041/gate',),created_at=FIXED)\nclass TestUMD041(unittest.TestCase):\n  def test_foundation(self): self.assertTrue(certify_umd_041_foundation()['certified'])\n  def test_valid_admitted(self):\n    m=model(); d=evaluate_active_market_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model(m,lineage=gate_lineage(m)); self.assertTrue(d.admitted); self.assertTrue(all(d.checks.values()))\n  def test_deterministic(self):\n    m=model(); l=gate_lineage(m); a=evaluate_active_market_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model(m,lineage=l); b=evaluate_active_market_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model(m,lineage=l); self.assertEqual(a.record_hash,b.record_hash)\n  def test_immutable(self):\n    m=model(); d=evaluate_active_market_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model(m,lineage=gate_lineage(m));\n    with self.assertRaises((FrozenInstanceError,AttributeError)): d.admitted=False\n    with self.assertRaises(TypeError): d.checks['x']=False\n  def test_lineage_requires_both(self):\n    m=model(); bad=ImmutableLineage(subsystem_id='UMD',build_id='UMD-041',revision=UMD_041_REVISION,schema_version='1.0.0',parent_hashes=(m.read_model_hash,),source_refs=('fixture://bad',),created_at=FIXED)\n    with self.assertRaises(ValueError): evaluate_active_market_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_ledger_read_model(m,lineage=bad)\n  def test_side_effects(self):\n    x=build_umd_041_certification_manifest(); self.assertFalse(x.network_enabled); self.assertFalse(x.persistence_enabled); self.assertFalse(x.mutation_enabled); self.assertFalse(x.publication_enabled); self.assertFalse(x.execution_enabled)\nif __name__=='__main__':\n print('='*72); print(' UMD-041 CERTIFICATION TEST'); print('='*72)\n r=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(TestUMD041))\n if not r.wasSuccessful(): raise SystemExit(1)\n m=build_umd_041_certification_manifest(); print(f'[PASS] Build: {m.build_id}'); print(f'[PASS] Revision: {m.revision}'); print(f'[PASS] Manifest hash: {m.manifest_hash}'); print('[PASS] UMD-001 through UMD-040 consumed read-only'); print('[PASS] Exact UMD-040 read-model class consumed'); print('[PASS] Immutable UMD-041 admission decisions certified'); print('[PASS] Network, persistence, publication, and execution disabled'); print('[DONE] UMD-041 CERTIFIED')\n"
